import { type Conf, splitTop, stripComment, unquote } from "./confmap.ts";

const KEY =
  /^(?:"([^"]+)"|'([^']+)'|([^\s"'#-][^:]*?|-[^\s][^:]*?))\s*:(?:\s+(.*))?$/;

const indentOf = (line: string): number =>
  line.length - line.trimStart().length;

/** Adds `item` to the list at `path`. A key with no value becomes a list. */
